const pres = new pptxgen();
pres.layout = 'LAYOUT_WIDE';
pres.author = 'OpenAI Codex';
pres.subject = 'JavaScript Rising Stars 2024';
pres.title = '2024 JavaScript Rising Stars: Top Projects and Ecosystem Shifts';
pres.company = 'Best of JS (data source context)';
pres.lang = 'en-US';

const theme = {
  primary: '0F172A',
  secondary: '334155',
  accent: '2563EB',
  light: '93C5FD',
  bg: 'F8FAFC'
};

for (let i = 1; i <= 8; i++) {
  const num = String(i).padStart(2, '0');
  const mod = require(`./slide-${num}.js`);
  mod.createSlide(pres, theme);
}

pres.writeFile({ fileName: '/app/output/final_deck.pptx' });
